import Head from "next/head";
import { useRouter } from "next/router";
import { SITE_URL } from "../../lib/constants";

// Canonical URL and machine-readable alternates for every page. The files they
// point at are generated by lib/modules/generate-agent-files.mjs.
export default function DiscoveryLinks() {
  const router = useRouter();
  if (router.pathname === "/404" || router.pathname === "/_error") return null;

  const pathOnly = router.asPath.split(/[?#]/)[0];
  const markdownPath = pathOnly === "/" ? "/index.md" : `${pathOnly}.md`;

  return (
    <Head>
      <link key="canonical" rel="canonical" href={SITE_URL + pathOnly} />
      <link key="alternate-markdown" rel="alternate" type="text/markdown" href={markdownPath} />
      <link key="describedby-llms" rel="describedby" type="text/markdown" href="/llms.txt" />
      <link
        key="alternate-rss"
        rel="alternate"
        type="application/rss+xml"
        title="Ali Aljufairi · Notes on ML & Cloud"
        href="/feed.xml"
      />
      <link key="sitemap" rel="sitemap" type="application/xml" href="/sitemap.xml" />
    </Head>
  );
}
